import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>100KB下，格式的选择决定了图片看起来有多好。同一张照片，用一种格式可能很清晰，换一种就可能发灰。</p>\n<p>JPG、PNG和WebP存储图片的方式各不相同。文件预算一收紧，它们的长处和短处就都显出来了。</p>\n<p>这篇文章会在100KB下对比这三种格式，帮你为照片、图形、截图和标志选出正确的那一个。</p>\n<h2 id=\"how-each-format-works\">每种格式是怎么存图片的？</h2>\n<p>JPG用的是有损压缩。它扔掉眼睛几乎察觉不到的数据，这就是它能把照片压得这么小的原因。</p>\n<p>PNG用的是无损压缩。它把每个像素都原样保留下来，这对图形来说很完美，对照片来说却很贵。</p>\n<p>WebP用的是更现代的有损压缩，算法比JPG更好。同样文件大小下，它能保留更多细节。</p>\n<p>100KB下，这些差别很重要。JPG和WebP有发挥的空间，PNG常常没有。</p>\n<h2 id=\"jpg-at-100kb\">100KB下的JPG</h2>\n<p>JPG是网上的主力格式。100KB下，一张普通的照片能保持自然的样子，只有轻微的发虚。</p>\n<p>肤色是JPG的强项。它把平滑的渐变融合得很干净，所以人像看起来自然，不会斑驳。</p>\n<p>它的弱点是锐利的边缘。文字和细线条可能出现淡淡的光晕，尤其是在高对比的背景上。</p>\n<p>兼容性是JPG最大的资产。每个报名网站、邮件客户端和设备打开JPG都不用多想。</p>\n<h2 id=\"webp-at-100kb\">100KB下的WebP</h2>\n<p>同样文件大小下，WebP通常胜过JPG。边缘更干净，渐变更平滑，细腻的细节保留得更好。</p>\n<p>优势不大，但是真实的。100KB下并排对比，大多数人会觉得WebP那张更锐利。</p>\n<p>WebP还支持透明背景，JPG做不到。这让它成为边缘柔和的图形的不错选择。</p>\n<p>缺点是接受度。有些老旧的报名网站、邮件客户端和政府表格仍然直接拒绝WebP文件。</p>\n<h2 id=\"png-at-100kb\">100KB下的PNG</h2>\n<p>PNG在100KB下不适合照片。一张细节丰富的照片存成PNG，可能要把尺寸砍掉一半才能塞进去。</p>\n<p>PNG赢的地方是图形。颜色扁平的标志、图表或示意图，用PNG能做到像素级完美。</p>\n<p>文字是PNG的另一个强项。白底上的锐利黑字，用PNG能保持清晰，JPG做不到这一点。</p>\n<p>透明背景是选择PNG的最后一个理由。图片需要透明背景时，只有PNG或WebP可选。</p>\n<h2 id=\"photos-compared\">照片在100KB下的对比</h2>\n<p>拿一张人像来说。JPG格式100KB下，脸部看起来自然，头发保留了大部分纹理。</p>\n<p>WebP格式100KB下，同一张人像看起来锐利一点点。差别很小，但凑近了看确实存在。</p>\n<p>PNG格式100KB下，这张人像就失败了。工具必须大幅缩小尺寸才能塞进去，结果看起来又小又虚。</p>\n<p>照片的排名很清楚：WebP第一，JPG紧随其后，PNG远远落后。</p>\n<h2 id=\"graphics-compared\">图形和文字在100KB下的对比</h2>\n<p>拿一张线条细、标签小的图表来说。PNG下每条线都精确无误，每个标签都保持可读。</p>\n<p>JPG下，同一张图表会在文字周围出现晕染。标签依然能读，但看起来有点脏。</p>\n<p>WebP下，图表介于两者之间。它比JPG干净，对大多数图形来说几乎和PNG一样好。</p>\n<p>图形的排名正好反过来：PNG第一，WebP第二，JPG第三。内容类型决定了胜者。</p>\n<h2 id=\"screenshots-compared\">截图在100KB下的对比</h2>\n<p>截图混合了照片、文字和扁平的界面颜色。没有一种格式能同时把这三样都做到完美。</p>\n<p>PNG能让文字保持完美，但文件会变得巨大。一张全屏截图用PNG可能有好几MB。</p>\n<p>JPG能轻松把截图压小，但小字会变虚。小于12像素的标签可能变得难以阅读。</p>\n<p>WebP是截图最好的折中方案。它的小字比JPG干净得多，同时到达100KB也不费力。</p>\n<h2 id=\"transparency-compared\">100KB下的透明背景</h2>\n<p>带透明背景的标志不能用JPG。这种格式完全不支持透明。</p>\n<p>PNG处理透明背景非常完美。边缘保持干净，背景依然透明。</p>\n<p>WebP也支持透明背景，而且文件通常比PNG更小。网页标志用WebP常常是更好的选择。</p>\n<p>如果目的地是只接受JPG的报名网站，你必须先把透明部分压平。背景通常会变成白色。</p>\n<h2 id=\"which-format-when\">什么时候用哪种格式？</h2>\n<p>照片要发给报名网站、邮件或老系统时用JPG。它是永远不会被拒绝的安全选择。</p>\n<p>照片和截图要放在现代网站上时用WebP。三种格式里，它每KB的画质最好。</p>\n<p>标志、图表和带透明背景的图形用PNG。只有它能让扁平图形保持像素级完美。</p>\n<p>拿不准时，JPG和WebP都试一遍。同一张图片压缩两次，并排预览后再做决定。</p>\n<h2 id=\"testing-method\">自己测试格式的方法</h2>\n<p>挑一张有代表性的图片，不要挑最简单的那张。一张带文字的细节照片，最能显出格式之间的差别。</p>\n<p>用<a href=\"/zh/tupian-yasuo-dao-100kb/\">100KB压缩工具</a>把每种格式都压到100KB。尺寸保持一致，测试才公平。</p>\n<p>三张都用全尺寸查看。放大同一个区域，对比同样的细节。</p>\n<p>文件大小也要看。如果WebP轻松就落在了100KB以下，说明它完成任务更容易，画质差距可能比看起来更大。</p>\n<ul>\n<li>发给报名网站的照片：JPG，通用接受。</li>\n<li>现代网站上的照片：WebP，结果最锐利。</li>\n<li>标志和图表：PNG，边缘像素级完美。</li>\n<li>截图：WebP，平衡最好。</li>\n<li>透明图片：PNG或WebP，绝不用JPG。</li>\n</ul>\n<p>格式选择是个小决定，回报却看得见。花两分钟测试一下，你的100KB图片就会达到最佳状态。</p>\n<h2 id=\"colour-depth\">色彩深度，以及它在100KB下为什么重要</h2>\n<p>色彩深度是指图片能显示的颜色范围。照片用的是数百万种颜色，简单的图形可能只有几百种。</p>\n<p>100KB下，压缩器会简化颜色来省空间。平滑的渐变最先遭殃，因为它们需要很多相近的色调。</p>\n<p>人像在这方面表现很好，因为皮肤只用很窄的色调范围。一张脸的颜色比落日少得多，所以损失也更少。</p>\n<p>色彩丰富的场景受损更大。一个摆满几十种鲜艳布料的市场摊位，需要更多数据才能让每种颜色保持分明。</p>\n<p>WebP处理颜色简化的能力比JPG稍好一点。如果你的图片色彩非常丰富，试试WebP，再对比两张结果。</p>\n<h2 id=\"sharpness-vs-smoothness\">锐利与平滑：选你的优先级</h2>\n<p>每次压缩都要在锐利和平滑之间取舍。更锐利的图片边缘清晰，但噪点更多；更平滑的图片藏住了噪点，但边缘会变虚。</p>\n<p>人像照片偏爱平滑。皮肤稍微柔和一点，比稍微带噪点看起来更好，眼睛对柔和的皮肤更宽容。</p>\n<p>文字和图形偏爱锐利。发虚的图表就是一张没用的图表，边缘必须保持清晰，哪怕背景带点噪点。</p>\n<p>二分搜索会自动找到平衡。它会选能塞进去的最高画质，这个点通常正好落在你的内容最合适的甜点附近。</p>\n<p>自动结果感觉不对时，试试另一种格式。JPG偏平滑，WebP偏锐利，这个差别常常就够了。</p>\n<h2 id=\"format-myths\">值得忽略的格式误区</h2>\n<p>一个误区说PNG的画质永远比JPG高。这只对图形成立，100KB下的照片，PNG要差得多。</p>\n<p>另一个误区说WebP看起来比JPG差。实际上，几乎每次同样大小的测试里，WebP都和JPG打平或胜过JPG。</p>\n<p>第三个误区说转换格式一定会毁掉画质。从PNG到JPG的一次干净转换，损失远小于硬把PNG压到100KB。</p>\n<p>解决这些问题最好的办法就是测试。同一张图片每种格式压一次，相信自己的眼睛。</p>\n<p>决定胜者的是你的内容，而不是格式的名声。照片、图形和截图，各自都有最适合的格式。</p>\n<h2 id=\"archiving-100kb\">以100KB存档图片</h2>\n<p>100KB的文件是交付格式，不是存档格式。它是为上传做的，不是为永远保存做的。</p>\n<p>原图要以完整画质存档。100KB的副本没法放大、重印或重新编辑而不出现可见损伤。</p>\n<p>100KB的副本用来分享和发布。它们加载快、能通过上传上限，在屏幕上也好看。</p>\n<p>存档文件夹按日期和事件命名。2026-11-family-trip这样的文件夹放原图，100KB的副本放在博客文章或申请材料旁边。</p>\n<p>以后还需要100KB的版本时，从存档重新做一份。千万别再压缩旧的100KB副本。</p>\n<h2 id=\"quick-reference\">快速参考：100KB下的格式选择</h2>\n<p>发给报名网站和邮件的照片：JPG。到处都被接受，100KB下看起来很干净。</p>\n<p>现代网站上的照片：WebP。同样大小下稍微锐利一点，页面也更轻。</p>\n<p>标志、图表和扁平图形：PNG。边缘像素级完美，还支持透明背景。</p>\n<p>带文字的截图：先选WebP，再选JPG。WebP在100KB下小字更干净。</p>\n<p>透明图片：只能用PNG或WebP。JPG存不了透明背景，只会把背景填满。</p>\n<h2 id=\"lossy-vs-lossless\">有损与无损：这场对比背后的核心概念</h2>\n<p>每个格式决定都从一个问题开始：这种压缩是有损还是无损？答案决定了后面的一切。</p>\n<p>JPG和WebP这样的有损格式会永久扔掉数据。损失一开始看不见，文件越小就越明显。</p>\n<p>PNG这样的无损格式会把每个像素原样保留。代价是体积：无损的照片常常比有损的大十倍。</p>\n<p>100KB下，有损格式有充裕的发挥空间。无损的PNG几乎没有空间，这就是它处理照片会失败的原因。</p>\n<p>理解这一个区别，就能解释这篇文章里的大多数结果。有损格式赢在照片，无损格式赢在图形，内容说了算。</p>\n<h2 id=\"browser-support\">每种格式的浏览器与设备支持</h2>\n<p>JPG到处都能用。过去二十年生产的每台浏览器、手机、邮件客户端和打印机，打开JPG都不用多想。</p>\n<p>WebP在所有现代浏览器里都能用，包括Chrome、Firefox、Safari和Edge。不过老系统和一些政府网站仍然拒绝它。</p>\n<p>PNG到处也都能用。它之所以能一直作为标志和界面图形的默认格式，通用支持就是原因之一。</p>\n<p>目的地不确定时，JPG是最安全的选择。目的地是现代网站时，WebP通常是更好的选择。</p>\n<p>选择之前先确认目的地。对方打不开的格式，比稍微柔和一点的图片还要糟糕。</p>\n<h2 id=\"future-formats\">WebP之后是什么？</h2>\n<p>AVIF这样的新格式承诺在同样画质下文件比WebP更小。测试里表现很亮眼，但还没有普及。</p>\n<p>目前，实用的选择仍然在JPG、PNG和WebP之间。这三种格式能覆盖100KB下所有真实的需求。</p>\n<p>浏览器的AVIF支持在增长，但很多报名网站和邮件客户端仍然打不开它。现在用它，有被拒绝上传的风险。</p>\n<p>100KB压缩工具聚焦在人们真正能用的格式上。等AVIF普及了，选择自然会变宽。</p>\n<p>在那之前，先掌握这篇文章里的三种格式。它们能处理你要压缩的每一张照片、图形和截图。</p>\n<h2 id=\"how-quality-is-picked\">压缩器如何为每种格式挑选画质</h2>\n<p>二分搜索对每种格式的工作方式是一样的，但结果不同。JPG和WebP在比PNG高得多的画质设置下就能到达100KB。</p>\n<p>照片用JPG时，搜索可能停在80%左右的画质，WebP下还会稍高一点。两种设置下的结果都很干净。</p>\n<p>图形的搜索表现不一样。一张PNG图表可能要大幅裁尺寸才能到达100KB，同一张图表用WebP却轻松塞得进去。</p>\n<p>工具不会给每张图片硬套同一个画质数值。它会为每个文件重新搜索，因为每张图片都有自己最合适的设置。</p>\n<p>正是这种逐张搜索，让工具胜过手动猜测。固定的70%画质，对有些图片太狠，对有些图片又太宽松。</p>\n<p>想看通用指南，可以读<a href=\"/zh/blog/tu-pian-ya-suo-dao-100kb-wan-zheng-zhi-nan/\">图片压缩到100KB：完整指南</a>。想看操作步骤，可以参考<a href=\"/zh/blog/ru-he-ba-tu-pian-suo-xiao-dao-100kb/\">如何把图片缩小到100KB</a>。如果需要先在格式之间转换，<a href=\"/zh/zhuanhuan-tupian/\">图片转换工具</a>能完成这一步。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"100KB下WebP是不是永远比JPG好？","answer":"画质上通常是的，但只好一点点。同样文件大小下，WebP的边缘更干净。兼容性上JPG仍然胜出，因为有些报名网站和老系统不接受WebP。接受WebP的地方用WebP，可能不接受的地方用JPG。"},{"question":"为什么我的照片用PNG压到100KB后更难看了？","answer":"PNG无损存储图片，细节丰富的照片需要的空间远超100KB。为了塞进去，工具必须大幅缩小尺寸，结果看起来又小又虚。PNG是为图形设计的，不是为照片设计的。"},{"question":"能把PNG照片转成JPG来达到100KB吗？","answer":"可以，而且通常效果很好。把PNG照片转成JPG，是达到100KB又保住画质的最快方法。只有图片需要透明背景时才不要这样做，因为JPG存不了透明背景。"},{"question":"WebP的颜色和JPG一样吗？","answer":"一样，普通照片的颜色非常接近。WebP能存更平滑的渐变，有时看起来颜色更干净。任何差别都很细微，来自更好的压缩，而不是颜色本身变了。"},{"question":"100KB的扫描件应该用哪种格式？","answer":"JPG通常最适合100KB的扫描件，因为扫描件的表现和照片很像。如果文件基本是白底黑字、没有照片，PNG能让文字更锐利，但可能需要更小的尺寸才能塞进去。"},{"question":"转换格式会降低图片画质吗？","answer":"从PNG转成JPG或WebP是有损步骤，确实会损失一点画质。但从高质量的PNG出发、只转换一次，效果远比硬把PNG本身压到100KB要好。一次干净的转换，胜过一个被挤压的PNG。"}];
